// --- Rule table ---
export const RuleProvenanceSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('builtin') }),
  z.object({
    kind: z.literal('proposal'),
    proposalId: nonEmpty(),
    producer: nonEmpty().optional(),
  }),
  z.object({ kind: z.literal('import'), source: nonEmpty() }),
]);
